import sqlite3

conn = sqlite3.connect(":memory:")
conn.execute("CREATE TABLE users (name TEXT, role TEXT)")
conn.executemany("INSERT INTO users VALUES (?, ?)", [("anna", "admin"), ("boris", "user"), ("clara", "user")])



def bad(role):
    return len(conn.execute(f"SELECT name FROM users WHERE role = '{role}'").fetchall())


def good(role):
    return len(conn.execute("SELECT name FROM users WHERE role = ?", (role,)).fetchall())


print(bad("user"), good("user"))
print(bad("x' OR '1'='1"), good("x' OR '1'='1"))
